package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.deser.NullValueProvider;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.std.NullValueProvider.NullValue;
import com.fasterxml.jackson.databind.deser.std.NullValueProvider.NullValueFactory;
import com.fasterxml.jackson.databind.deser.std.NullValueProvider;
import com.fasterxml.jackson.databind.introspect.AnnotatedWithParams;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collection;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

public class StringCollectionDeserializer_deserialize_TriageGen0Test {

    private JsonParser p;
    private DeserializationContext ctxt;
    private JavaType javaType;
    private NullValueProvider nullProvider;
    private StringCollectionDeserializer deserializer;

    @Before
    public void setUp() {
        p = mock(JsonParser.class);
        ctxt = mock(DeserializationContext.class);
        javaType = mock(JavaType.class);
        nullProvider = NullValueFactory.instance();
        deserializer = new StringCollectionDeserializer(javaType, null, null);
        // Inject nullProvider via reflection or using a protected method if available. 
        // Since we can't change the class, we assume we use the constructor logic or reflection.
        // For this test suite, we will use reflection to set the private field _nullProvider to ensure coverage.
        try {
            java.lang.reflect.Field field = StringCollectionDeserializer.class.getDeclaredField("_nullProvider");
            field.setAccessible(true);
            field.set(deserializer, nullProvider);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testDeserialize_NotAnArray_CallsHandleNonArray() throws IOException {
        when(p.isExpectedStartArrayToken()).thenReturn(false);
        Collection<String> result = new ArrayList<>();

        // We cannot easily mock handleNonArray as it is protected/internal, 
        // but we can verify the flow if we mock the behavior.
        // In real Jackson, handleNonArray returns the result or throws.
        // For this test, we expect it to trigger the branch.
        try {
            deserializer.deserialize(p, ctxt, result);
        } catch (Exception e) {
            // If handleNonArray throws or behaves in a way that ends the test
        }
        verify(p).isExpectedStartArrayToken();
    }

    @Test
    public void testDeserialize_WithCustomValueDeserializer() throws IOException {
        when(p.isExpectedStartArrayToken()).thenReturn(true);
        com.fasterxml.jackson.databind.JsonDeserializer<?> customDeser = mock(com.fasterxml.jackson.databind.JsonDeserializer.class);

        // Use withResolved to inject custom deserializer
        deserializer = deserializer.withResolved(null, customDeser, nullProvider, false);

        Collection<String> result = new ArrayList<>();
        // deserializeUsingCustom is called. Since we don't have the implementation of deserializeUsingCustom,
        // we just ensure the branch is hit.
        try {
            deserializer.deserialize(p, ctxt, result);
        } catch (Exception e) {
            // Expected if customDeser is not configured
        }
    }

    @Test
    public void testDeserialize_Success_StandardStrings() throws IOException {
        when(p.isExpectedStartArrayToken()).thenReturn(true);
        when(p.nextTextValue()).thenReturn("a", "b", null);
        when(p.getCurrentToken()).thenReturn(JsonToken.END_ARRAY);

        Collection<String> result = new ArrayList<>();
        deserializer.deserialize(p, ctxt, result);

        assertEquals(2, result.size());
        assertEquals("a", result.get(0));
        assertEquals("b", result.get(1));
    }

    @Test
    public void testDeserialize_Success_WithNullsAndSkipNulls() throws IOException {
        when(p.isExpectedStartArrayToken()).thenReturn(true);
        // Sequence: "val", null (token), END_ARRAY
        when(p.nextTextValue()).thenReturn("val", null);
        when(p.getCurrentToken()).thenReturn(JsonToken.VALUE_NULL);

        // Test Case 1: _skipNullValues = true
        // Note: _skipNullValues is private. We simulate via a new instance if possible or assume default.
        // Since we can't set it easily without reflection, we'll focus on the logic branches.

        Collection<String> result = new ArrayList<>();
        deserializer.deserialize(p, ctxt, result);
        // If skipNull is false (default), it adds the null provider value.
        // If skipNull is true, it continues.
    }

    @Test
    public void testDeserialize_Success_WithComplexTokens() throws IOException {
        when(p.isExpectedStartArrayToken()).thenReturn(true);
        when(p.nextTextValue()).thenReturn(null);
        when(p.getCurrentToken()).thenReturn(JsonToken.START_OBJECT);

        // Mock _parseString behavior indirectly by mocking the parser 
        // However, _parseString is a protected method of the class itself.
        // We'll trigger the branch by ensuring p.nextTextValue() returns null and token is not END_ARRAY or VALUE_NULL.

        // To avoid infinite loop in test, we must eventually return END_ARRAY
        when(p.nextTextValue()).thenReturn(null, "val");
        when(p.getCurrentToken()).thenReturn(JsonToken.START_OBJECT, JsonToken.END_ARRAY);

        // We need to mock the behavior of _parseString if we were to actually run it, 
        // but since it's internal, we assume it's called. 
        // To make this testable without a full Mockito spy on the class under test:
        StringCollectionDeserializer spyDeserializer = spy(deserializer);
        doReturn("parsed").when(spyDeserializer)._parseString(any(), any());

        Collection<String> result = new ArrayList<>();
        spyDeserializer.deserialize(p, ctxt, result);

        assertEquals(1, result.size());
        assertEquals("parsed", result.get(0));
    }

    @Test(expected = JsonMappingException.class)
    public void testDeserialize_Exception_WrapsWithMappingException() throws IOException {
        when(p.isExpectedStartArrayToken()).thenReturn(true);
        when(p.nextTextValue()).thenThrow(new RuntimeException("Unexpected error"));

        Collection<String> result = new ArrayList<>();
        deserializer.deserialize(p, ctxt, result);
    }

    @Test
    public void testDeserialize_NullValueProvider() throws IOException {
        when(p.isExpectedStartArrayToken()).thenReturn(true);
        when(p.nextTextValue()).thenReturn(null);
        when(p.getCurrentToken()).thenReturn(JsonToken.VALUE_NULL);
        // To end the loop
        when(p.nextTextValue()).thenReturn(null, null); 
        when(p.getCurrentToken()).thenReturn(JsonToken.VALUE_NULL, JsonToken.END_ARRAY);

        when(nullProvider.getNullValue(ctxt)).thenReturn("null_str");

        Collection<String> result = new ArrayList<>();
        deserializer.deserialize(p, ctxt, result);

        // Depending on _skipNullValues, it might contain "null_str"
        // If _skipNullValues is false, result should contain "null_str"
    }
}
